typedef struct { float (*get_celsius)(void *ctx); void *ctx; } CelsiusReporter;
typedef struct { float (*get_kelvin)(void *ctx); void *ctx; } KelvinReporter;

static float to_kelvin(void *ctx) {          /* adapter callback */
    CelsiusReporter *r = ctx;                /* recover the adaptee */
    return r->get_celsius(r->ctx) + 273.15f; /* and translate units */
}

static KelvinReporter adapt(CelsiusReporter *r) {
    KelvinReporter k = { .get_kelvin = to_kelvin, .ctx = r };
    return k;                                /* caller uses k.get_kelvin */
}

