struct foreach_ctx { Foreach target; void *user; };

static void node_adapter(size_t i, Node *n, void *ctx) {
    struct foreach_ctx *c = ctx;             /* recover state */
    c->target(i, n->data, c->user);          /* adapt arguments */
}

void foreach(List *l, Foreach f, void *user) {
    struct foreach_ctx c = { f, user };
    foreach_node(l, node_adapter, &c);
}
